function t(key){return (translations[state.language]&&translations[state.language][key])||translations.en[key]||key;}
function readSaved(){try{return JSON.parse(localStorage.getItem('apphoryn-saved')||'[]')}catch{return []}}
function saveSaved(){localStorage.setItem('apphoryn-saved',JSON.stringify(state.saved));}
function esc(value=''){return String(value).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));}
function toast(message,error=false){const node=document.createElement('div');node.className='toast'+(error?' error':'');node.textContent=message;$('toastRegion').appendChild(node);setTimeout(()=>node.remove(),4200);}
function recordStoreEvent(eventType,appSlug='',artifactId='',query=''){
 const body={event_type:eventType,app_slug:appSlug||null,artifact_id:artifactId||null,details:query?{query}:{}};
 fetch('/api/v1/analytics/events',{
  method:'POST',
  headers:{'Content-Type':'application/json','Accept':'application/json'},
  credentials:'omit',
  keepalive:true,
  body:JSON.stringify(body)
 }).catch(()=>{});
}
function applyLanguage(language){state.language=translations[language]?language:'en';localStorage.setItem('apphoryn-language',state.language);document.documentElement.lang=state.language;document.documentElement.dir=state.language==='ar'?'rtl':'ltr';$('languageSelect').value=state.language;$('settingsLanguage').value=state.language;document.querySelectorAll('[data-i18n]').forEach(el=>{const key=el.dataset.i18n;const value=t(key);if(value.includes('<br>')||value.includes('<em>'))el.innerHTML=value;else el.textContent=value});document.querySelectorAll('[data-i18n-placeholder]').forEach(el=>el.placeholder=t(el.dataset.i18nPlaceholder));document.title='Apphoryn — '+t('heroTitle').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();renderCategories();renderApps();renderDiscovery();renderSaved();renderDownloads();renderAiStatus();renderAutomationJobs();renderSourceQueue();$('pageCrumb').textContent=document.querySelector('.nav-link.active [data-i18n]')?.textContent||t('overview');}
function navigate(view){const target=$('view-'+view);if(!target)return;document.querySelectorAll('.view').forEach(el=>el.classList.toggle('active',el===target));document.querySelectorAll('.nav-link[data-view]').forEach(el=>el.classList.toggle('active',el.dataset.view===view));const active=document.querySelector('.nav-link.active [data-i18n]');$('pageCrumb').textContent=active?.textContent||view;history.replaceState(null,'','#'+view);closeSidebar();if(view==='builds')loadJobs(true);if(view==='downloads')renderDownloads();}
function closeSidebar(){$('sidebar').classList.remove('open');$('sidebarScrim').classList.remove('open');}
function localizedSummary(app){const value=app.translations&&app.translations[state.language];return typeof value==='string'&&!value.trim().startsWith('{')?value:(app.summary||app.description||'');}
function localizedDescription(app){const value=app.description_translations&&app.description_translations[state.language];return typeof value==='string'&&!value.trim().startsWith('{')?value:(app.description||app.summary||'');}
function appIconMarkup(app,className='app-logo'){
 const initial=esc((app.name||'?').trim().slice(0,1).toUpperCase());
 const url=String(app.icon_url||'');
 const avatar=/^https:\/\/avatars\.githubusercontent\.com\/(?:u\/)?\d+(?:\?[^#]*)?$/i.test(url);
 const repository=String(app.repository_url||'').match(/^https:\/\/github\.com\/([A-Za-z0-9_.-]+)\/([A-Za-z0-9_.-]+)$/i);
 const raw=repository&&url.startsWith(`https://raw.githubusercontent.com/${repository[1]}/${repository[2]}/`)&&!/[?#]/.test(url);
 const safe=avatar||raw;
 return `<div class="${className}"><span>${initial}</span>${safe?`<img src="${esc(url)}" alt="" loading="eager" decoding="async" referrerpolicy="no-referrer" onerror="this.remove()">`:''}</div>`;
}
function isApphorynReleaseAsset(url){try{const parsed=new URL(String(url||''));return parsed.protocol==='https:'&&parsed.hostname==='github.com'&&!parsed.username&&!parsed.password&&!parsed.search&&!parsed.hash&&parsed.pathname.startsWith('/ibra8y3-web/Apphoryn/releases/download/');}catch{return false;}}
function appCard(app){const saved=state.saved.includes(app.id);const artifacts=app.artifacts||[];const platforms=[...new Set(artifacts.map(a=>a.platform))];return `<article class="app-card" data-app-id="${esc(app.id)}"><div class="app-card-top">${appIconMarkup(app)}<div class="app-card-main"><h3>${esc(app.name)}</h3><div class="app-owner">${esc(app.owner||'')} · ${esc(app.latest_version||'Source project')}</div></div><button class="save-button ${saved?'saved':''}" data-save="${esc(app.id)}" aria-label="Save app">${saved?'♥':'♡'}</button></div><p class="app-summary">${esc(localizedSummary(app))}</p><div class="tag-row"><span class="tag">${esc(app.category||'other')}</span>${platforms.map(p=>`<span class="tag platform">${esc(p)}</span>`).join('')}</div><div class="app-card-bottom"><span class="license-label">${esc(app.license_spdx||'License not identified')}</span><span class="artifact-count"><strong>${artifacts.length}</strong> ${t('packages')}</span></div></article>`;}
function renderApps(){const query=($('catalogSearch')?.value||'').toLowerCase().trim();const category=$('categoryFilter')?.value||'all';const apps=state.apps.filter(app=>(category==='all'||app.category===category)&&(!query||`${app.name} ${app.summary} ${app.owner} ${app.category}`.toLowerCase().includes(query)));$('appCount').textContent=state.apps.length;$('metricApps').textContent=state.apps.length;$('metricPackages').textContent=state.apps.reduce((sum,a)=>sum+(a.artifacts||[]).length,0);$('metricVerified').textContent=state.apps.reduce((sum,a)=>sum+(a.artifacts||[]).filter(x=>x.upstream_digest_verified).length,0);$('featuredGrid').innerHTML=state.apps.length?state.apps.slice(0,3).map(appCard).join(''):`<div class="empty-state"><div class="empty-symbol">◈</div><b>${t('noAppsYet')}</b><p>${t('noAppsHint')}</p><button class="button button-outline" data-go="discovery">${t('startDiscovering')}</button></div>`;$('catalogGrid').innerHTML=apps.length?apps.map(appCard).join(''):`<div class="empty-state"><div class="empty-symbol">◈</div><b>${t('emptyCatalog')}</b><p>${t('emptyCatalogDesc')}</p></div>`;renderDownloads();}
function renderCategories(){const host=$('categoryGrid');if(!host)return;host.innerHTML=categoryMeta.map(([id,key,icon])=>{const count=state.apps.filter(app=>app.category===id).length;return `<article class="category-card" data-category="${id}"><div class="category-icon">${icon}</div><b>${t(key)}</b><small>${count} ${t('apps')}</small></article>`}).join('');}
function renderDiscovery(){
 const host=$('discoveryResults');if(!host)return;
 if(!state.discovery.length){host.innerHTML=`<div class="empty-state compact"><div class="empty-symbol">⌕</div><b>${t('searchToDiscover')}</b><p>${t('discoveryDisclaimer')}</p></div>`;$('discoveryCount').textContent='—';return;}
 $('discoveryCount').textContent=`${state.discovery.length} ${t('searchResults')}`;
 host.innerHTML=state.discovery.map(item=>{
  const eligible=item.license_eligible&&!item.archived;
  const existing=(state.sourceApps||[]).find(app=>String(app.repository_url||'').toLowerCase()===String(item.repository_url||'').toLowerCase());
  const installable=existing&&(existing.artifacts||[]).length>0;
  const status=item.archived?t('archived'):installable?t('alreadyInstallable'):existing?t('alreadyScouted'):eligible?t('scoutWillReview'):t('notEligible');
  const link=String(item.repository_url||'');
  return `<article class="discovery-item">${appIconMarkup(item,'discovery-logo')}<div class="discovery-info"><h3>${esc(item.full_name)}</h3><p>${esc(item.description||'')}</p><div class="discovery-meta"><span class="tag">${esc(item.license_spdx||t('noLicense'))}</span><span class="tag">${Number(item.stars||0).toLocaleString()} ${t('stars')}</span>${(item.topics||[]).slice(0,3).map(topic=>`<span class="tag">${esc(topic)}</span>`).join('')}</div></div><div class="discovery-action"><span class="eligibility ${eligible?'':'blocked'}">${esc(status)}</span><a class="tiny-button" href="${esc(link)}" target="_blank" rel="noopener noreferrer">${t('viewSource')} ↗</a></div></article>`;
 }).join('');
}
function renderSaved(){const host=$('savedGrid');if(!host)return;const apps=state.apps.filter(app=>state.saved.includes(app.id));host.innerHTML=apps.length?apps.map(appCard).join(''):`<div class="empty-state"><div class="empty-symbol">♡</div><b>${t('nothingSaved')}</b><p>${t('saveAppsHint')}</p></div>`;}
function nativeStorePlatform(){
 if(window.ApphorynNative&&typeof window.ApphorynNative.installArtifact==='function')return 'android';
 if(!window.ApphorynInstaller||typeof window.ApphorynInstaller.installArtifact!=='function')return '';
 const ua=navigator.userAgent||'';
 if(/Windows NT/i.test(ua))return 'windows';
 if(/Macintosh|Mac OS X/i.test(ua))return 'macos';
 if(/Linux/i.test(ua))return 'linux';
 return '';
}
function artifactCanInstallHere(artifact){
 const platform=nativeStorePlatform();
 const extension=String(artifact.filename||'').split('.').pop().toLowerCase();
 const allowed={android:['apk','xapk'],windows:['exe','msi','msix','appx'],linux:['deb','rpm','appimage'],macos:['pkg','dmg']};
 return Boolean(platform&&artifact.platform===platform&&(allowed[platform]||[]).includes(extension));
}
function installButton(artifact){
 if(!artifactCanInstallHere(artifact)){
  const platformLabel=String(artifact.platform||'other').toUpperCase();
  return `<span class="install-platform-label">${esc(platformLabel)}</span>`;
 }
 return `<button type="button" class="tiny-button" data-install-artifact="${esc(artifact.id||artifact.sha256||'')}">${t('install')} ↓</button>`;
}
async function installArtifact(artifactId){
 const artifact=state.apps.flatMap(item=>item.artifacts||[]).find(item=>String(item.id||item.sha256||'')===String(artifactId));
 if(!artifact){toast(t('noArtifacts'),true);return}
 const downloadUrl=String(artifact.download_url||'');
 if(!isApphorynReleaseAsset(downloadUrl)){toast(t('packageUnavailable'),true);return}
 const ownerApp=state.apps.find(item=>(item.artifacts||[]).some(row=>String(row.id||row.sha256||'')===String(artifactId)));
 if(ownerApp)recordStoreEvent('download_requested',String(ownerApp.slug||''),String(artifact.id||artifact.sha256||''));
 const payload={apiBase:'',artifactId:String(artifact.id||artifact.sha256||''),filename:String(artifact.filename||''),platform:String(artifact.platform||''),packageType:String(artifact.package_type||''),sha256:String(artifact.sha256||''),downloadUrl};
 try{
  if(window.ApphorynNative&&typeof window.ApphorynNative.installArtifact==='function'){
   window.ApphorynNative.installArtifact(payload.apiBase,payload.artifactId,payload.filename,payload.platform,payload.packageType,payload.sha256,payload.downloadUrl);
   toast(t('installing'));
   return;
  }
  if(window.ApphorynInstaller&&typeof window.ApphorynInstaller.installArtifact==='function'){
   toast(t('installing'));
   await window.ApphorynInstaller.installArtifact(payload);
   return;
  }
  toast(t('nativeClientRequired'),true);
 }catch(error){toast(error.message||t('nativeClientRequired'),true)}
}
function renderDownloads(){const host=$('downloadsList');if(!host)return;const items=state.apps.flatMap(app=>(app.artifacts||[]).map(artifact=>({...artifact,appName:app.name})));host.innerHTML=items.length?items.map(item=>`<article class="artifact-row"><div class="artifact-icon">⇩</div><div class="artifact-info"><b>${esc(item.filename)}</b><small>${esc(item.appName)} · ${esc(item.platform)} · ${formatBytes(item.size_bytes)}</small></div><span class="artifact-hash" title="SHA-256 ${esc(item.sha256)}">${esc((item.sha256||'').slice(0,12))}…</span>${installButton(item)}</article>`).join(''):`<div class="empty-state compact"><div class="empty-symbol">⇩</div><b>${t('noPackages')}</b></div>`;}

function formatBytes(bytes){const n=Number(bytes||0);if(n<1024)return `${n} B`;const units=['KB','MB','GB','TB'];let value=n/1024,index=0;while(value>=1024&&index<units.length-1){value/=1024;index++}return `${value.toFixed(value>=10?0:1)} ${units[index]}`;}
const GITHUB_REPOSITORY = "ibra8y3-web/Apphoryn";
const GITHUB_API_ROOT = "https://api.github.com";
const REDISTRIBUTION_LICENSES = new Set([
 "MIT","Apache-2.0","BSD-2-Clause","BSD-3-Clause","ISC","MPL-2.0",
 "GPL-2.0","GPL-2.0-only","GPL-2.0-or-later","GPL-3.0","GPL-3.0-only",
 "GPL-3.0-or-later","LGPL-2.1","LGPL-2.1-only","LGPL-2.1-or-later",
 "LGPL-3.0","LGPL-3.0-only","LGPL-3.0-or-later","AGPL-3.0",
 "AGPL-3.0-only","AGPL-3.0-or-later","0BSD","Zlib","Unlicense","BSL-1.0"
]);
async function githubJson(url){
 const response=await fetch(url,{headers:{Accept:"application/vnd.github+json"},cache:"no-store",mode:"cors"});
 let payload={};
 try{payload=await response.json()}catch{}
 if(!response.ok){
  if(response.status===403||response.status===429)throw new Error("GitHub search limit reached. Try again later; Apphoryn Scout keeps running automatically.");
  throw new Error(payload.message||("GitHub returned HTTP "+response.status));
 }
 return payload;
}
function renderAiStatus(){
 const host=$("aiProvidersList");
 const headline=$("aiEngineHeadline");
 const note=$("aiStatusNote");
 if(!host)return;
 const report=state.aiStatus;
 if(report&&Array.isArray(report.providers)&&report.providers.length){
  const available=Number(report.available_provider_count||0);
  const models=Number(report.available_model_count||0);
  if(headline)headline.textContent=available
   ? (state.language==="ar"?"محرك النماذج متصل":"Model router online")
   : (state.language==="ar"?"لا يوجد نموذج متاح حاليًا":"No model provider is currently available");
  host.innerHTML=report.providers.map(item=>{
   const status=String(item.state||"unknown");
   const label=state.language==="ar"
    ? (status==="available"?"متاح":status==="paused"?"مضبوط ومتوقف":status==="not_configured"?"غير مربوط":"غير متاح")
    : (status==="available"?"Available":status==="paused"?"Configured · paused":status==="not_configured"?"Not configured":"Unavailable");
   const count=Number(item.models_discovered||0);
   const models=Array.isArray(item.models)?item.models:[];
   const modelHtml=models.map(model=>'<span class="provider-model">'+esc(model.model)+(model.free_class?'<small>'+esc(model.free_class)+'</small>':'')+'</span>').join('');
   return '<div class="provider-row"><div class="provider-main"><b>'+esc(item.provider)+'</b><span class="provider-state '+esc(status)+'">'+label+(count?" · "+count:"")+'</span>'+(modelHtml?'<div class="provider-models">'+modelHtml+'</div>':'')+'</div></div>';
  }).join("");
  if(note)note.textContent=(report.free_only
    ? (state.language==="ar"?"وضع المجاني مفعّل؛ لا يتم اختيار نماذج مدفوعة تلقائيًا. ":"Free-only routing is enabled; paid models are not selected automatically. ")
    : (state.language==="ar"?"وضع المجاني غير مفعّل. ":"Free-only routing is disabled. "))
    + (state.language==="ar"?"آخر فحص: ":"Last checked: ")+(report.checked_at?new Date(report.checked_at).toLocaleString(state.language):"—")
    +" · "+models+" "+(state.language==="ar"?"نموذج متاح":"available models");
  return;
 }
 const usage={};
 for(const app of state.sourceApps||[]){
  const provider=String(app.ai_provider||"");
  if(provider)usage[provider]=(usage[provider]||0)+1;
 }
 const rows=Object.entries(usage);
 if(headline)headline.textContent=rows.length
  ? (state.language==="ar"?"الذكاء الاصطناعي أنشأ بيانات تطبيقات بالفعل":"AI has generated catalog metadata")
  : (state.language==="ar"?"تقرير حالة النماذج لم يصل بعد":"Waiting for the first provider health report");
 host.innerHTML=rows.length?rows.map(([provider,count])=>'<div class="provider-row"><b>'+esc(provider)+'</b><span class="provider-state available">'+count+(state.language==="ar"?" وصفًا تم إنشاؤه":" generated records")+'</span></div>').join("")
  : '<div class="empty-state compact">'+(state.language==="ar"?"لم ينشر Scout حالة النماذج بعد.":"Scout has not published a model status report yet.")+'</div>';
 if(note)note.textContent=state.language==="ar"
  ?"الأعداد هنا من بيانات التطبيقات التي أنشأها الذكاء الاصطناعي سابقًا، وليست فحصًا حيًا للمفاتيح."
  :"This fallback reflects providers recorded on AI-generated app metadata; it is not a live credential check.";
}
function renderSourceQueue(){
 const host=$("sourceProjectsList");
 if(!host)return;
 const items=(state.sourceApps||[])
  .filter(app=>!Array.isArray(app.artifacts)||app.artifacts.length===0)
  .slice()
  .sort((left,right)=>new Date(right.source_updated_at||right.updated_at||right.created_at||0)-new Date(left.source_updated_at||left.updated_at||left.created_at||0))
  .slice(0,12);
 const count=(state.sourceApps||[]).filter(app=>!Array.isArray(app.artifacts)||app.artifacts.length===0).length;
 if($("sourceQueueCount"))$("sourceQueueCount").textContent=String(count);
 if(!items.length){
  host.innerHTML='<div class="empty-state compact"><b>'+esc(t("noSourceProjects"))+'</b></div>';
  return;
 }
 host.innerHTML=items.map(app=>{
  const attempts=Array.isArray(app.build_attempts)?app.build_attempts:[];
  const latest=attempts.slice().sort((x,y)=>new Date(y.requested_at||0)-new Date(x.requested_at||0))[0];
  const latestAt=latest?.requested_at?new Date(latest.requested_at):null;
  const recentAttempt=latestAt&&Number.isFinite(latestAt.getTime())&&(Date.now()-latestAt.getTime()<72*60*60*1000);
  let stateLabel,stateClass;
  if(recentAttempt){
   stateLabel=t("buildDispatched");
   stateClass="queued";
  }else if(app.build_recommended===true){
   stateLabel=t("buildCandidate");
   stateClass="candidate";
  }else{
   stateLabel=t("sourceOnlyLabel");
   stateClass="source";
  }
  const targets=Array.isArray(latest?.targets)?latest.targets.filter(Boolean).join(", "):"";
  const summary=localizedSummary(app)||app.description||"";
  const repo=String(app.repository_url||"");
  const safeRepo=repo.startsWith("https://github.com/")?repo:"#";
  const icon=appIconMarkup(app,"source-project-logo");
  const model=app.ai_provider?String(app.ai_provider)+(app.ai_model?" · "+String(app.ai_model):""):"";
  const meta=[app.project_kind||"",app.license_spdx||"",app.latest_version||""].filter(Boolean).map(esc).join(" · ");
  const dispatchNote=recentAttempt?(targets?" · "+targets:""):"";
  return '<article class="source-project-row">'+icon+'<div class="source-project-info"><div class="source-project-title"><b>'+esc(app.name||app.slug||"Source project")+'</b><span class="source-project-state '+stateClass+'">'+esc(stateLabel)+'</span></div><p>'+esc(summary)+'</p><small>'+meta+'</small>'+(model?'<small class="source-project-ai">'+esc(model)+'</small>':'')+(recentAttempt&&latestAt?'<small>'+esc(t("buildRequested"))+' '+esc(latestAt.toLocaleString(state.language))+esc(dispatchNote)+'</small>':'')+'</div><a class="tiny-button source-project-link" href="'+esc(safeRepo)+'" target="_blank" rel="noopener noreferrer">'+t("viewSource")+' ↗</a></article>';
 }).join("");
}
function updateAutomationCounters(){
 const source=state.sourceApps||[];
 const installable=(state.apps||[]).length;
 const sourceOnly=source.filter(item=>!Array.isArray(item.artifacts)||!item.artifacts.length).length;
 if($("scoutCatalogCount"))$("scoutCatalogCount").textContent=source.length;
 if($("scoutInstallableCount"))$("scoutInstallableCount").textContent=installable;
 if($("scoutSourceCount"))$("scoutSourceCount").textContent=sourceOnly;
 renderAiStatus();
 renderSourceQueue();
}
async function loadCatalog(){
 const applyManifest=(manifest,status)=>{
  const records=Array.isArray(manifest.apps)?manifest.apps:[];
  state.sourceApps=records;
  state.aiStatus=manifest.ai_status||null;
  state.apps=records.filter(app=>Array.isArray(app.artifacts)&&app.artifacts.length>0).map(app=>({...app,id:app.id||app.slug,artifacts:app.artifacts.map(artifact=>({...artifact,id:artifact.id||artifact.sha256}))}));
  $("apiStatus").textContent=status;
  $("apiStatus").className="status-tag";
  $("lastUpdated").textContent=manifest.generated_at?new Date(manifest.generated_at).toLocaleString(state.language,{dateStyle:"medium",timeStyle:"short"}):"—";
  renderApps();renderCategories();renderSaved();updateAutomationCounters();
 };
 try{
  const liveUrl="https://raw.githubusercontent.com/"+GITHUB_REPOSITORY+"/main/apps/web/catalog/index.json?refresh="+Date.now();
  const response=await fetch(liveUrl,{cache:"no-store",mode:"cors"});
  if(!response.ok)throw new Error("Live catalogue returned HTTP "+response.status);
  applyManifest(await response.json(),"LIVE CATALOG");
  return;
 }catch(liveError){
  try{
   const response=await fetch(new URL("catalog/index.json",document.baseURI),{cache:"no-store"});
   if(!response.ok)throw new Error("Bundled catalogue returned HTTP "+response.status);
   applyManifest(await response.json(),"OFFLINE COPY");
  }catch(error){
   $("apiStatus").textContent="OFFLINE";
   $("apiStatus").style.color="var(--amber)";
   toast(state.language==="ar"?"تعذر تحميل كتالوج Apphoryn.":"Could not load the Apphoryn catalog.",true);
  }
 }
}
function runTitle(run){
 const name=String(run.name||"");
 if(name.includes("Scout"))return state.language==="ar"?"كشاف التطبيقات — بحث واستيراد":"Scout — discover and import";
 if(name.includes("Build and publish community software"))return state.language==="ar"?"بناء تطبيق مكتشف":"Automatic application build";
 if(name.includes("Build Apphoryn native store clients"))return state.language==="ar"?"بناء تطبيق المتجر":"Store client build";
 return name;
}
function runStatus(run){
 if(run.status==="completed"){
  if(run.conclusion==="success")return state.language==="ar"?"نجح":"Succeeded";
  if(run.conclusion==="failure")return state.language==="ar"?"فشل":"Failed";
  if(run.conclusion==="cancelled")return state.language==="ar"?"أُلغي":"Cancelled";
  return String(run.conclusion||"completed");
 }
 if(run.status==="queued"||run.status==="waiting")return state.language==="ar"?"في الانتظار":"Queued";
 return state.language==="ar"?"يعمل الآن":"Running";
}
function renderAutomationJobs(){
 const host=$("jobsList");
 if(!host)return;
 const relevant=(state.jobs||[]).filter(run=>/Apphoryn Scout|Build and publish community software|Build Apphoryn native store clients/.test(String(run.name||""))).slice(0,12);
 const latestScout=relevant.find(run=>String(run.name||"").includes("Scout"));
 if($("scoutLastRun"))$("scoutLastRun").textContent=latestScout
  ? runStatus(latestScout)+" · "+new Date(latestScout.created_at).toLocaleString(state.language)
  : (state.language==="ar"?"لم يصل تشغيل بعد":"No run reported yet");
 if($("metricJobs"))$("metricJobs").textContent=relevant.filter(run=>String(run.name||"").includes("Build and publish community software")).length;
 if(!relevant.length){
  host.innerHTML='<div class="empty-state compact"><b>'+ (state.language==="ar"?"لا توجد مهام مسجلة بعد":"No automation runs reported yet")+'</b><p>'+(state.language==="ar"?"سيظهر تشغيل Scout والبناء هنا من GitHub Actions.":"Scout and build runs will appear here from GitHub Actions.")+'</p></div>';
  return;
 }
 host.innerHTML=relevant.map(run=>{
  const success=run.status==="completed"&&run.conclusion==="success";
  const failure=run.status==="completed"&&run.conclusion==="failure";
  const stateClass=success?"success":failure?"failure":run.status==="in_progress"?"running":"";
  const url=String(run.html_url||"");
  const safeUrl=url.startsWith("https://github.com/"+GITHUB_REPOSITORY+"/actions/runs/")?url:"#";
  const time=run.created_at?new Date(run.created_at).toLocaleString(state.language):"";
  return '<article class="job-row"><span class="job-state '+stateClass+'"></span><div class="job-info"><b>'+esc(runTitle(run))+'</b><small>'+esc(time)+' · '+esc(String(run.event||""))+'</small></div><span class="job-status">'+esc(runStatus(run))+'</span><a class="job-open" href="'+esc(safeUrl)+'" target="_blank" rel="noopener noreferrer">↗</a></article>';
 }).join("");
}
async function loadJobs(force=false){
 if(!force&&Date.now()-state.jobsFetchedAt<60000&&state.jobs.length){renderAutomationJobs();return;}
 const cacheKey="apphoryn-public-actions-cache";
 try{
  const payload=await githubJson(GITHUB_API_ROOT+"/repos/"+GITHUB_REPOSITORY+"/actions/runs?per_page=30");
  state.jobs=Array.isArray(payload.workflow_runs)?payload.workflow_runs:[];
  state.jobsFetchedAt=Date.now();
  try{localStorage.setItem(cacheKey,JSON.stringify(state.jobs));}catch{}
  renderAutomationJobs();
 }catch(error){
  try{
   const cached=JSON.parse(localStorage.getItem(cacheKey)||"[]");
   if(Array.isArray(cached)&&cached.length)state.jobs=cached;
  }catch{}
  renderAutomationJobs();
  if(!state.jobs.length&&$("jobsList"))$("jobsList").innerHTML='<div class="empty-state compact"><b>'+esc(error.message)+'</b></div>';
 }
}
function openApp(id){
 const app=state.apps.find(item=>item.id===id);if(!app)return;
 recordStoreEvent('app_view',String(app.slug||''));
 const artifacts=app.artifacts||[];
 $('modalContent').innerHTML=`<div class="modal-header">${appIconMarkup(app)}<div><h2 id="modalTitle">${esc(app.name)}</h2><p>${esc(app.owner)} · ${esc(app.latest_version||t('sourceOnly'))}</p></div></div><p class="modal-description">${esc(localizedDescription(app))}</p><div class="tag-row"><span class="tag">${esc(app.category)}</span><span class="tag">${esc(app.license_spdx||'')}</span><span class="tag">${artifacts.length} ${t('packages')}</span></div><div class="modal-section"><h3>${t('packageTypes')}</h3>${artifacts.length?artifacts.map(artifact=>`<div class="modal-artifact"><div><b>${esc(artifact.filename)}</b><small>${esc(artifact.platform)} · ${formatBytes(artifact.size_bytes)} · SHA-256 ${esc((artifact.sha256||'').slice(0,12))}…</small><small>${artifact.upstream_digest_verified?t('artifactVerified'):t('artifactHashLocal')}</small></div>${installButton(artifact)}</div>`).join(''):`<p class="form-note">${t('noArtifacts')}</p>`}</div>`;
 $('modalBackdrop').classList.add('open');
}
async function searchDiscovery(query){
 if(!query.trim())return;
 const button=$('discoveryButton');button.disabled=true;button.textContent=t('searching');
 $('discoveryResults').innerHTML=`<div class="empty-state compact"><b>${t('searching')}</b></div>`;
 try{
  const url=GITHUB_API_ROOT+"/search/repositories?q="+encodeURIComponent(query)+"&sort=updated&order=desc&per_page=25";
  const payload=await githubJson(url);
  const rows=Array.isArray(payload.items)?payload.items:[];
  state.discovery=rows.map(repo=>({
   name:repo.name||'',
   full_name:repo.full_name||'',
   description:repo.description||'',
   repository_url:repo.html_url||'',
   icon_url:repo.owner?.avatar_url||null,
   license_spdx:repo.license?.spdx_id||null,
   license_eligible:REDISTRIBUTION_LICENSES.has(String(repo.license?.spdx_id||'')),
   archived:Boolean(repo.archived),
   stars:Number(repo.stargazers_count||0),
   updated_at:repo.updated_at||null,
   default_branch:repo.default_branch||'main',
   topics:Array.isArray(repo.topics)?repo.topics:[]
  }));
  renderDiscovery();
 }catch(error){
  $('discoveryResults').innerHTML=`<div class="empty-state compact"><b>${esc(error.message)}</b><p>${t('scoutAutoNote')}</p></div>`;
 }finally{
  button.disabled=false;button.innerHTML=`${t('searchGithub')} ↗`;
 }
}
function toggleSaved(id){const exists=state.saved.includes(id);state.saved=exists?state.saved.filter(item=>item!==id):[...state.saved,id];saveSaved();renderApps();renderSaved();const app=state.apps.find(item=>String(item.id)===String(id));if(app)recordStoreEvent(exists?'favorite_removed':'favorite_added',String(app.slug||''));toast(t(exists?'removedToast':'savedToast'));}
function attachEvents(){
 document.addEventListener('click',event=>{
  const nav=event.target.closest('[data-view]');
  if(nav){event.preventDefault();navigate(nav.dataset.view);return;}
  const go=event.target.closest('[data-go]');
  if(go){navigate(go.dataset.go);return;}
  const category=event.target.closest('[data-category]');
  if(category){navigate('explore');$('categoryFilter').value=category.dataset.category;renderApps();return;}
  const save=event.target.closest('[data-save]');
  if(save){event.stopPropagation();toggleSaved(save.dataset.save);return;}
  const install=event.target.closest('[data-install-artifact]');
  if(install){event.stopPropagation();installArtifact(install.dataset.installArtifact);return;}
  const card=event.target.closest('[data-app-id]');
  if(card&&!event.target.closest('a')){openApp(card.dataset.appId);return;}
  const queryButton=event.target.closest('[data-query]');
  if(queryButton){$('discoveryQuery').value=queryButton.dataset.query;searchDiscovery(queryButton.dataset.query);return;}
 });
 $('discoveryForm').addEventListener('submit',event=>{event.preventDefault();searchDiscovery($('discoveryQuery').value);});
 $('catalogSearch').addEventListener('input',renderApps);
 $('catalogSearch').addEventListener('change',event=>recordStoreEvent('search','','',String(event.target.value||'')));
 $('categoryFilter').addEventListener('change',renderApps);
 $('languageSelect').addEventListener('change',event=>{applyLanguage(event.target.value);toast(t('languageChanged'));});
 $('settingsLanguage').addEventListener('change',event=>{applyLanguage(event.target.value);toast(t('languageChanged'));});
 $('menuToggle').addEventListener('click',()=>{$('sidebar').classList.add('open');$('sidebarScrim').classList.add('open');});
 $('sidebarScrim').addEventListener('click',closeSidebar);
 $('modalClose').addEventListener('click',()=>$('modalBackdrop').classList.remove('open'));
 $('modalBackdrop').addEventListener('click',event=>{if(event.target===$('modalBackdrop'))$('modalBackdrop').classList.remove('open');});
 $('refreshJobs').addEventListener('click',()=>loadJobs(true));
 $('themeToggle').addEventListener('click',()=>{document.body.classList.toggle('light');localStorage.setItem('apphoryn-theme',document.body.classList.contains('light')?'light':'dark');});
 document.addEventListener('keydown',event=>{
  if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();navigate('explore');$('catalogSearch').focus();}
  if(event.key==='Escape'){$('modalBackdrop').classList.remove('open');closeSidebar();}
 });
}
async function init(){if(localStorage.getItem('apphoryn-theme')==='light')document.body.classList.add('light');applyLanguage(state.language);attachEvents();await Promise.all([loadCatalog(),loadJobs(true)]);recordStoreEvent('catalog_view');const hash=location.hash.replace('#','');if(hash&&$('view-'+hash))navigate(hash);}
init();
